INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65152482', 65152482, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pemeliharaan Kebersihan Gedung Kantor PMO', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 288000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Tahun', 'Pemeliharaan kebersihan gedung dan taman wajib memenuhi kriteria sebagai berikut : 1. Kebersihan Lantai a. Lantai bersih tanpa ada noda kotoran; b. Lantai bersih tanpa noda bekas air pel yang mengering; c. Lantai bersih tanpa menimbulkan bau yang tidak enak Kebersihan dinding a. Dinding dengan permukaan cat harus bersih tidak terdapat noda kotoran maupun percikan air/kotoran lain; b. Dinding dengan permukaan wallpaper harus bersih dan tidak terdapat noda kotoran; c. Dinding dengan permukaan kayu harus bersih, tidak ada noda dan finisihing kayu terlihat mengkilap; d. Dinding dengan permukaan kaca harus bersih tidak terdapat noda kotoran, debu dan bekas sapuan air. 3. Kebersihan Toilet a. Permukaan lantai, dinding dan peralatan sanitair harus bersih tanpa bekas noda kotoran atau berkarat; b. Tidak ada genangan air atau bekas air mengering; c. Tidak berbau; d. Nat lantai dan dinding tetap berwarna putih; e. Tissue dan kamper tetap terisi sesuai persyaratan; f. Ketersediaan sabun tangan (hand soap) setiap saat untuk seluruh toilet. Sabun tangan (hand soap) menggunakan dispenser soap yang ditempatkan menempel didinding toilet. 4. Pembersihan Plafond Plafond tetap bersih seperti warna aslinya dan tidak terdapat sarang labalaba dan serangga. 5. Pembersihan Furniture Ruangan Seluruh furniture dalam ruangan bebas dari debu dan kotoran hingga sela-sela.', '-', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1970066);
