INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65192349', 65192349, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Perkebunan', 'Pengawasan Green House', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Sumedang (Kab.)', 18000000, 'June 2026', 'APBD', 1, 1, '1 paket', 'Lingkup pekerjaan utama yang masuk ke dalam tugas pengawasan ini termasuk ke dalam kategori Bangunan Gedung', 'Lingkup pekerjaan yang harus dilaksanakan Konsultan Pengawas adalah: 1. Memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawassn pekerjaan di lapangan. 2. Mengawasi pemakaian bahan, peralatan dan metode pelaksanaan, serta mengawasi ketepatan waktu dan biaya pekerjaan konstruksi 3. Mengawasi pelaksanaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume atau realisasi fisik 4. Mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pelaksanaan konstruksi 5. Meneliti gambar – gambar untuk pelaksanaan (shop drawing) yang diajukan oleh kontraktor pelaksana. 6. Meneliti gambar – gambar yang sesuai dengan pelaksanaan di lapangan (As bulit drawing) sebelum serah terima pekerjaan 7. Menyampaikan surat teguran kepada kontraktor pelaksana ketika terjadi keterlambatan pekerjaan dan/atau ditemukan ketidaksesuaian antara perencanaan dan pelaksanaan di lapangan 8. Menyusun daftar cacat atau kerusakan sebelum serah terima pertama, mengawasi perbaikannya pada masa pemeliharaan, dan menyusun laporan akhir pekerjaan pengawasan 9. Menyusun Berita Acara Kemajuan Pekerjaan, Berita acara Pemeliharaan Pekerjaan, Berita acara Serah Terima pelaksanaan konstruksi sebagai kelengkapan untuk pembayaran pekerjaan konstruksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1971036);
