INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65156220', 65156220, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Model Pendekatan Keterkaitan Pembiayaan Investasi terhadap Prioritas Nasional 6 yang Mendukung Pencapaian Rencana Pembangunan Jangka Menengah 2025-2029', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 94800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kebijakan dan Regulasi Pembangunan Ruang lingkup kajian meliputi kebijakan fiskal, dukungan pembiayaan dan investasi, serta regulasi yang relevan dapat mendukung ketercapaian Prioritas Nasional 6. Indikator Pembangunan Prioritas Nasional 6 dan Kerangka Metodologis Ruang lingkup mencakup indikator - indikator pembangunan Prioritas Nasional 6 sebagaimana tercantum dalam RPJMN 2025 – 2029, termasuk kerangka teori, pendekatan metodologi pengukuran, serta keterkaitannya dengan pembiayaan dan investasi pembangunan. Inventarisasi Program dan Keluaran Pembangunan Ruang lingkup mencakup pemetaan Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO), dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi pada sektor Prioritas Nasional 6. Model Pendekatan Pembiayaan dan Investasi Ruang lingkup mencakup pengembangan kerangka model pendekatan yang menjelaskan keterkaitan antara pembiayaan, investasi, kapasitas fiskal, dan capaian Prioritas Nasional 6 dengan opsi model kuantitatif/kualitatif/hybrid. Kesenjangan Pembiayaan dan Investasi Ruang lingkup mencakup identifikasi dan analisis kesenjangan (gap analysis) antara kebutuhan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 6. Rekomendasi Strategis Kebijakan Ruang lingkup mencakup perumusan arah dan opsi strategis kebijakan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 6. Penyusunan Dokumen dan Bahan Pendukung Ruang lingkup mencakup penyusunan dokumen kajian, laporan berkala, bahan presentasi, dan dokumen pendukung lainnya yang diperlukan dalam rangka pelaksanaan kegiatan sesuai arahan pimpinan.', 'Memiliki Pendidikan minimal S1 di bidang Teknik Industri/Ekonomi (dibuktikan dengan ijazah jenjang Pendidikan); Memiliki kemampuan yang baik dan berpengalaman dalam menulis, menyusun dokumen guidance yang berhubungan dengan kegiatan pemerintah; dan Memiliki pengalaman bekerja di sektor finansial/ekonomi diutamakan yang berpengalaman kerja dibidang pemerintahan minimal 3 tahun. Diutamakan menggunakan konsultan dalam negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP) dan NPWP. Pada pelaksanaan pekerjaan, Konsultan Junior: Tidak berhak mendapatkan fasilitas BMN, THR dan Gaji ke-13; Tidak mendapatkan fasilitas asuran seperti BPJS Kesehatan dan BPJS Ketenagakerjaan dari Pemilik Pekerjaan; Tidak memanfaatkan fasilitas klinik kantor secara gratis, kecuali dalam kondisi darurat kesehatan; Tidak ada ikatan atau tuntutan untuk diangkat menjadi ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1974385);
