INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65157827', 65157827, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Model Pendekatan Keterkaitan Pembiayaan Investasi terhadap Prioritas Nasional 3 yang Mendukung Pencapaian Rencana Pembangunan Jangka Menengah 2025-2029', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 83600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kebijakan dan Regulasi Pembangunan Ruang lingkup kajian meliputi kebijakan fiskal, dukungan pembiayaan dan investasi, serta regulasi yang relevan dapat mendukung ketercapaian Prioritas Nasional 3. Indikator Pembangunan Prioritas Nasional 5 dan kerangka Metodologis Ruang lingkup mencakup indikator - indikator pembangunan Prioritas Nasional 3 sebagaimana tercantum dalam RPJMN 2025 – 2029, termasuk kerangka teori, pendekatan metodologi pengukuran, serta keterkaitannya dengan pembiayaan dan investasi pembangunan. Inventarisasi Program dan Keluaran Pembangunan Ruang lingkup mencakup pemetaan Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO), dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi pada sektor Prioritas Nasional 3. Model Pendekatan Pembiayaan dan Investasi Ruang lingkup mencakup pengembangan kerangka model pendekatan yang menjelaskan keterkaitan antara pembiayaan, investasi, kapasitas fiskal, dan capaian Prioritas Nasional 3 dengan opsi model kuantitatif/kualitatif/hybrid. Kesenjangan Pembiayaan dan Investasi Ruang lingkup mencakup identifikasi dan analisis kesenjangan (gap analysis) antara kebutuhan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 3. Rekomendasi Strategis Kebijakan Ruang lingkup mencakup perumusan arah dan opsi strategis kebijakan pembiayaan dan investasi untuk mendukung pencapaian indikator Prioritas Nasional 3. Penyusunan Dokumen dan Bahan Pendukung Ruang lingkup mencakup penyusunan dokumen kajian, laporan berkala, bahan presentasi, dan dokumen pendukung lainnya yang diperlukan dalam rangka pelaksanaan kegiatan sesuai arahan pimpinan. Output/Keluaran Keluaran yang diharapkan adalah berupa output based per termin yaitu “Dokumen Model Pendekatan Keterkaitan Pembiayaan dan Investasi Terhadap Prioritas Nasional 3 yang Mendukung Pencapaian Rencana Pembangunan Jangka Menengah 2025-2029” diantaranya meliputi: Laporan hasil inventarisasi kebijakan, kegiatan dan regulasi telaah implementasi kebijakan, kegiatan, dan regulasi yang berkaitan dengan upaya pencapaian indikator RPJMN pada sektor Prioritas Nasional 3. Laporan mengenai landasan teori atau landasan metodologi, cara perhitungan pencapaian indikator-indikator atau index yang menjadi referensi pada sektor Prioritas Nasional 3. Laporan identifikasi dan inventarisasi Program Prioritas (PP), Kegiatan Prioritas (KP), Proyek Prioritas (Pro-P), Klasifikasi Rincian Output (KRO) dan Rincian Output (RO) yang didukung oleh pembiayaan dan investasi untuk sektor Prioritas Nasional 3. Laporan hasil studi pustaka, analisa, dan penyusunan model keterkaitan pembiayaan investasi dengan opsi model kuantitatif/kualitatif/hybrid yang paling mendekati kondisi aktual. Laporan penyusunan analisa kesenjangan (gap analysis) kebutuhan pembiayaan dan investasi pada sektor Prioritas Nasional 3 serta langkah-langkah rekomendasi untuk mengatasi kesenjangan tersebut.', 'Memiliki Pendidikan minimal S1 di bidang Ilmu Ekonomi (dibuktikan dengan ijazah jenjang Pendidikan); Memiliki pengalaman bekerja di sektor ekonomi/keuangan/kebijakan publik diutamakan yang berpengalaman kerja dibidang penelitian dan pemerintahan minimal 1-2 Tahun; Memiliki Pemahaman yang baik terhadp Dokumen Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029; Memiliki pemahaman terkait dinamika kebijakan fiskal Indonesia; Memiliki kemampuan yang baik dan berpengalaman dalam menulis dokumen kebijakan. Memiliki Pendidikan minimal S1 di bidang Ilmu Ekonomi (dibuktikan dengan ijazah jenjang Pendidikan); Memiliki pengalaman bekerja di sektor ekonomi/keuangan/kebijakan publik diutamakan yang berpengalaman kerja dibidang penelitian dan pemerintahan minimal 1-2 Tahun; Memiliki Pemahaman yang baik terhadp Dokumen Rencana Pembangunan Jangka Menengah Nasional (RPJMN) 2025-2029; Memiliki pemahaman terkait dinamika kebijakan fiskal Indonesia; Memiliki kemampuan yang baik dan berpengalaman dalam menulis dokumen kebijakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1976153);
